      "body": "uniform float u_scale; uniform float u_flow; uniform float u_coverage; uniform float u_darken;\nvoid main(){\n  vec2 uv=v_texCoord; vec2 p=uv*ASP()*u_scale; float t=u_time*u_flow*0.1;\n  vec3 dark=tex(uv)*(1.0-u_darken*0.8);\n  vec2 q=vec2(fbm(p+t), fbm(p+3.3-t));\n  float th=fbm(p*0.7+q*2.0);\n  float mask=smoothstep(1.0-u_coverage-0.1, 1.0-u_coverage+0.1, fbm(p*0.5+7.0+q*0.5));\n  vec3 film=thinfilm(th*3.0+0.2);\n  vec3 col=1.0-(1.0-dark)*(1.0-film*mask*0.55);\n  fragColor0=vec4(clamp(col,0.0,1.0),1.0);\n}"
