      "body": "uniform float u_bands; uniform float u_swirl; uniform float u_speed; uniform float u_mix;\nvoid main(){\n  vec2 uv=v_texCoord; vec2 p=uv*ASP()*2.0; float t=u_time*u_speed*0.1;\n  vec2 w=p+(vec2(fbm(p*1.3+t), fbm(p*1.3+6.0-t))-0.5)*u_swirl;\n  w+=(vec2(fbm(w*2.0-t), fbm(w*2.0+2.0+t))-0.5)*u_swirl*0.5;\n  float b=fract(dot(w,vec2(0.7,0.7))*u_bands);\n  vec3 film=thinfilm(b*1.5);\n  vec3 base=tex(uv);\n  vec3 ov=mix(2.0*base*film, 1.0-2.0*(1.0-base)*(1.0-film), step(0.5,base));\n  vec3 col=mix(base, ov, u_mix);\n  fragColor0=vec4(clamp(col,0.0,1.0),1.0);\n}"
