      "body": "uniform float u_horizon; uniform float u_mirage; uniform float u_strength; uniform float u_speed;\nvoid main(){\n  vec2 uv=v_texCoord;\n  vec2 np=vec2(uv.x*10.0, uv.y*30.0-u_time*u_speed);\n  vec2 n=(vec2(fbm(np), fbm(np+7.0))-0.5)*0.015*u_strength;\n  float near=exp(-abs(uv.y-u_horizon)*8.0);\n  vec3 col=tex(uv+n*near);\n  float band=0.12;\n  if(uv.y<u_horizon && uv.y>u_horizon-band){\n    float ry=2.0*u_horizon-uv.y;\n    vec3 refl=tex(vec2(uv.x,ry)+n*2.0);\n    float fade=1.0-(u_horizon-uv.y)/band;\n    col=mix(col, refl*vec3(0.95,0.97,1.05), fade*u_mirage);\n  }\n  fragColor0=vec4(clamp(col,0.0,1.0),1.0);\n}"
