      "body": "uniform float u_rings; uniform float u_warp; uniform float u_speed; uniform vec3 u_ink; uniform vec3 u_paper;\nvoid main(){\n  vec2 uv=v_texCoord; vec2 asp=ASP(); vec2 p=(uv-0.5)*asp; float t=u_time*u_speed*0.1;\n  p+=(vec2(fbm(p*2.0+t), fbm(p*2.0+4.0-t))-0.5)*u_warp*0.5;\n  float a=atan(p.y,p.x); p+=vec2(cos(a),sin(a))*sin(length(p)*6.0-t*3.0)*0.02*u_warp;\n  float d=1e9;\n  for(int i=0;i<3;i++){\n    float fi=float(i);\n    vec2 c=(vec2(h21(vec2(fi,u_seed+4.0)),h21(vec2(fi,u_seed+6.0)))-0.5)*0.6;\n    d=min(d, length(p-c));\n  }\n  float band=abs(fract(d*u_rings-t*0.5)-0.5)*2.0;\n  float ink=1.0-smoothstep(0.25,0.4,band);\n  vec3 col=mix(u_paper, u_ink, ink*0.85);\n  col*=0.97+0.03*vnoise(uv*asp*300.0);\n  fragColor0=vec4(col,1.0);\n}"
